import React from 'react';

import { WithChildren } from '../../../core/types/with-children.js';
import { useGridPlotSize } from '../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { XYChartXScalesContext } from '../context/XYChartXScalesContext.js';
import { generateScalesByXAxisId } from '../functions/generate-scales-by-x-axis-id.js';
import { useAxesConfig } from '../hooks/useAxesConfig.js';
import { useXYChartData } from '../hooks/useXYChartData.js';

export const XYChartXScalesProvider = ({ children }: WithChildren) => {
  const { data, seriesVariantsProps } = useXYChartData();
  const { width } = useGridPlotSize();
  const axes = useAxesConfig();

  const scales = generateScalesByXAxisId(
    axes,
    seriesVariantsProps,
    data,
    width,
  );

  return (
    <XYChartXScalesContext.Provider value={scales}>
      {children}
    </XYChartXScalesContext.Provider>
  );
};

XYChartXScalesProvider['displayName'] = 'XYChartXScaleProvider';
